namespace Mcs.Compiler;

/// <summary>
/// C# stub declarations for MC#'s built-in APIs.
/// Roslyn type-checks against these declarations, and the code generator reads
/// their attributes ([Intrinsic], [Nbt], [McAttribute], [McId], [State]) to decide which commands to emit.
/// The method bodies never run. EntityType and the per-block classes are generated by PreludeGen.
/// </summary>
public static class Prelude
{
    public const string GlobalUsings = """
        global using MCS;
        global using static MCS.Builtins;
        """;

    public const string Source = """
        namespace MCS
        {
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class IntrinsicAttribute : System.Attribute { public IntrinsicAttribute(string name) { } }

            /// Entity NBT path mapping. type: byte|short|int|long|float|double|string|int[]
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class NbtAttribute : System.Attribute { public NbtAttribute(string path, string type) { } }

            /// Entity attribute mapping (written without the "generic." prefix; the compiler adds it per version).
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class McAttributeAttribute : System.Attribute { public McAttributeAttribute(string id) { } }

            /// Minecraft ID (block / entity type / state value).
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class McIdAttribute : System.Attribute { public McIdAttribute(string id) { } }

            /// Block state property: state name and allowed values.
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class StateAttribute : System.Attribute { public StateAttribute(string name, string values) { } }

            /// Marks a class as an entity class: instances are entities of this type (+ tag).
            [System.AttributeUsage(System.AttributeTargets.Class)]
            public sealed class EntityAttribute : System.Attribute { public EntityAttribute(string type, string tag = null) { } }

            /// Per-entity scoreboard field. Default objective: <namespace>.<field_name>
            [System.AttributeUsage(System.AttributeTargets.Field)]
            public sealed class ScoreAttribute : System.Attribute
            {
                public ScoreAttribute(string objective = null) { }
                public string Display { get; set; }
                public string Color { get; set; }
                public string Criteria { get; set; }
            }

            /// The method body is inlined at each call site; constant arguments stay compile-time constants.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class InlineAttribute : System.Attribute { }

            /// Runs every time the datapack loads (#minecraft:load).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class LoadAttribute : System.Attribute { }

            /// Runs every tick (#minecraft:tick).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class TickAttribute : System.Attribute { }

            /// A compile-time position (an execute context + coordinates).
            public struct Position
            {
                [Intrinsic("pos.new")] public Position(double x, double y, double z) { }
                [Intrinsic("pos.here")] public static Position Here => default;
                [Intrinsic("pos.offset")] public Position Offset(double dx, double dy, double dz) => default;
            }

            /// Base class of entity classes ([Entity("minecraft:marker", "my.tag")] class Province : EntityObject).
            public abstract class EntityObject
            {
                [Intrinsic("ent.addtag")] public void AddTag(string tag) { }
                [Intrinsic("ent.removetag")] public void RemoveTag(string tag) { }
                [Intrinsic("ent.hastag")] public bool HasTag(string tag) => false;
                [Intrinsic("ent.kill")] public void Kill() { }
                [Intrinsic("ent.merge")] public void Merge(string snbt) { }
                [Intrinsic("ent.pos")] public Position Position => default;
                [Intrinsic("ent.tp")] public void Teleport(Position pos) { }
                [Intrinsic("ent.run")] public void Run(System.Action action) { }
            }

            /// Entity queries. Selector filters use selector syntax, e.g. "tag=a,scores={x=1..}".
            public static class Entities
            {
                [Intrinsic("ents.all")] public static System.Collections.Generic.IEnumerable<T> All<T>(string filter = "", bool at = false) where T : EntityObject => null;
                [Intrinsic("ents.spawn")] public static T Spawn<T>(Position pos, string nbt = "") where T : EntityObject => null;
                [Intrinsic("ents.nearest")] public static T Nearest<T>(Position pos, double maxDistance = -1, string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.random")] public static T Random<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.first")] public static T First<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.count")] public static int Count<T>(string filter = "") where T : EntityObject => 0;
                [Intrinsic("ents.any")] public static bool Any<T>(string filter = "") where T : EntityObject => false;
                [Intrinsic("ents.self")] public static T Self<T>() where T : EntityObject => null;
                [Intrinsic("ents.uuid")] public static T Uuid<T>(string uuid) where T : EntityObject => null;
            }

            /// Compile-time loops: foreach (int i in Unroll.Range(0, 3)) is expanded at compile time.
            public static class Unroll
            {
                [Intrinsic("unroll.range")] public static int[] Range(int from, int toExclusive) => null;
            }

            /// Execute contexts.
            public static class Exec
            {
                [Intrinsic("exec.run")] public static void Run(string subcommands, System.Action action) { }
                [Intrinsic("exec.at")] public static void At(Position pos, System.Action action) { }
            }

            public static class Builtins
            {
                [Intrinsic("asm")] public static void __asm(string commands) { }
                [Intrinsic("asmf")] public static void __asmf(string command) { }
                [Intrinsic("worldspawn")] public static Position GetWorldSpawn() => default;
                [Intrinsic("setworldspawn")] public static void SetWorldSpawn(Position pos) { }
                [Intrinsic("spawn.id")] public static void SpawnEntity(string id, Position pos, int count = 1) { }
            }
        }

        namespace EntityLib
        {
            public sealed class Entity
            {
                [MCS.Intrinsic("entity.new")] public Entity(EntityType type) { }

                [MCS.Nbt("Health", "float")] public float Health { get; set; }
                [MCS.McAttribute("max_health")] public float maxHealth { get; set; }
                [MCS.McAttribute("max_health")] public float MaxHealth { get; set; }
                [MCS.McAttribute("movement_speed")] public float MovementSpeed { get; set; }
                [MCS.McAttribute("attack_damage")] public float AttackDamage { get; set; }
                [MCS.McAttribute("armor")] public float Armor { get; set; }
                [MCS.Nbt("Fire", "short")] public int Fire { get; set; }
                [MCS.Nbt("Air", "short")] public int Air { get; set; }
                [MCS.Nbt("NoAI", "byte")] public bool NoAI { get; set; }
                [MCS.Nbt("Silent", "byte")] public bool Silent { get; set; }
                [MCS.Nbt("Glowing", "byte")] public bool Glowing { get; set; }
                [MCS.Nbt("Invulnerable", "byte")] public bool Invulnerable { get; set; }
                [MCS.Nbt("NoGravity", "byte")] public bool NoGravity { get; set; }
                [MCS.Nbt("PersistenceRequired", "byte")] public bool PersistenceRequired { get; set; }
                [MCS.Nbt("UUID", "int[]")] public int[] uuid => default!;
                [MCS.Nbt("UUID", "int[]")] public int[] UUID => default!;

                [MCS.Intrinsic("entity.pos")] public MCS.Position Position => default;
                [MCS.Intrinsic("entity.kill")] public void Kill() { }
                [MCS.Intrinsic("entity.tp")] public void Teleport(MCS.Position pos) { }
            }
        }

        namespace BlockLib
        {
            /// Base class of every block. `new Block : OakStairs s;` or `new Block("minecraft:stone")`.
            public class Block
            {
                [MCS.Intrinsic("block.new")] public Block(string id) { }
                protected Block(int _) { }
            }
        }

        namespace PlayerLib
        {
            public enum GameMode { Survival, Creative, Adventure, Spectator }

            /// Inventory slot numbers: 0–8 hotbar, 9–35 main inventory, plus the constants below.
            public static class Slot
            {
                public const int Feet = 100, Legs = 101, Chest = 102, Head = 103, Offhand = -106;
            }

            /// A set of players (a selector). Player.All, Player.Self, Player.Named("Steve") ...
            [MCS.Entity("minecraft:player")]
            public class Player : MCS.EntityObject
            {
                [MCS.Intrinsic("player.all")] public static Player All => default!;
                [MCS.Intrinsic("player.self")] public static Player Self => default!;
                [MCS.Intrinsic("player.nearest")] public static Player Nearest => default!;
                [MCS.Intrinsic("player.random")] public static Player Random => default!;
                [MCS.Intrinsic("player.named")] public static Player Named(string name) => default!;
                [MCS.Intrinsic("player.tagged")] public static Player WithTag(string tag) => default!;

                [MCS.Intrinsic("player.count")] public int Count => 0;
                [MCS.Intrinsic("player.exists")] public bool Exists => false;
                [MCS.Nbt("Health", "float")] public float Health => 0;
                [MCS.Nbt("foodLevel", "int")] public int Food => 0;
                [MCS.Nbt("XpLevel", "int")] public int Level { get; set; }
                [MCS.Nbt("SelectedItemSlot", "int")] public int SelectedSlot => 0;
                [MCS.Intrinsic("player.gamemode")] public GameMode GameMode { set { } }

                [MCS.Intrinsic("player.message")] public void SendMessage(params object[] parts) { }
                [MCS.Intrinsic("player.actionbar")] public void ActionBar(params object[] parts) { }
                [MCS.Intrinsic("player.title")] public void Title(object title, object subtitle = null) { }
                [MCS.Intrinsic("player.sound")] public void PlaySound(string sound, float volume = 1, float pitch = 1) { }
                [MCS.Intrinsic("player.setspawn")] public void SetSpawn(MCS.Position pos) { }
                [MCS.Intrinsic("player.addlevels")] public void AddLevels(int levels) { }
                [MCS.Intrinsic("player.addxp")] public void AddXp(int points) { }
                [MCS.Intrinsic("player.effect")] public void Effect(string effect, int seconds, int amplifier = 0, bool hideParticles = false) { }
                [MCS.Intrinsic("player.cleareffect")] public void ClearEffect(string effect) { }
                [MCS.Intrinsic("player.cleareffects")] public void ClearEffects() { }
                [MCS.Intrinsic("player.run")] public void Run(System.Action<Player> action) { }

                // Inventory
                [MCS.Intrinsic("player.give")] public void Give(string item, int count = 1) { }
                [MCS.Intrinsic("player.clearall")] public void ClearInventory() { }
                [MCS.Intrinsic("player.clearitem")] public void ClearItem(string item, int count = -1) { }
                [MCS.Intrinsic("player.countitem")] public int CountItem(string item) => 0;
                [MCS.Intrinsic("player.hasitem")] public bool HasItem(string item) => false;
                [MCS.Intrinsic("player.setslot")] public void SetSlot(int slot, string item, int count = 1) { }
                [MCS.Intrinsic("player.clearslot")] public void ClearSlot(int slot) { }
                [MCS.Intrinsic("player.slotcount")] public int GetSlotCount(int slot) => 0;
                [MCS.Intrinsic("player.slotis")] public bool IsSlot(int slot, string item) => false;
                [MCS.Intrinsic("player.slotempty")] public bool IsSlotEmpty(int slot) => false;
                [MCS.Intrinsic("player.copyslot")] public void CopySlot(int from, int to) { }
                [MCS.Intrinsic("player.moveslot")] public void MoveSlot(int from, int to) { }
                [MCS.Intrinsic("player.swapslots")] public void SwapSlots(int a, int b) { }
            }
        }

        namespace TuiLib
        {
            public enum Color { Black, DarkBlue, DarkGreen, DarkAqua, DarkRed, DarkPurple, Gold, Gray, DarkGray, Blue, Green, Aqua, Red, LightPurple, Yellow, White }

            /// A clickable chat button. Clicking it runs onClick as the player who clicked.
            public sealed class Button
            {
                [MCS.Intrinsic("tui.button")] public Button(string label, System.Action onClick) { }
                [MCS.Intrinsic("tui.button")] public Button(string label, System.Action<PlayerLib.Player> onClick) { }
                /// A button that runs a command (e.g. "trigger my.act set 3").
                [MCS.Intrinsic("tui.button")] public Button(string label, string command) { }
                public Color Color { get; set; }
                public string Hover { get; set; }
                public bool Bold { get; set; }
                public bool Underlined { get; set; }
            }

            /// Styled text.
            public sealed class Text
            {
                [MCS.Intrinsic("tui.text")] public Text(object content) { }
                public Color Color { get; set; }
                public bool Bold { get; set; }
                public bool Italic { get; set; }
                public bool Underlined { get; set; }
                public string Hover { get; set; }
            }

            public static class Tui
            {
                [MCS.Intrinsic("tui.print")] public static void Print(params object[] parts) { }
                [MCS.Intrinsic("tui.printto")] public static void PrintTo(PlayerLib.Player to, params object[] parts) { }
                [MCS.Intrinsic("tui.menu")] public static void Menu(PlayerLib.Player to, object title, params Button[] buttons) { }
                [MCS.Intrinsic("tui.clear")] public static void Clear(PlayerLib.Player to) { }
                [MCS.Intrinsic("tui.title")] public static void Title(PlayerLib.Player to, object title, object subtitle = null) { }
                [MCS.Intrinsic("tui.actionbar")] public static void ActionBar(PlayerLib.Player to, object text) { }
            }
        }

        public static class m
        {
            public static class Console
            {
                [MCS.Intrinsic("console.writeline")] public static void WriteLine(string text) { }
                [MCS.Intrinsic("console.writeline")] public static void WriteLine(object value) { }
            }

            [MCS.Intrinsic("spawn")] public static bool SpawnEntityObject(EntityLib.Entity entity, MCS.Position pos) => default;
            [MCS.Intrinsic("spawn.id")] public static void SpawnEntity(string id, MCS.Position pos, int count = 1) { }

            [MCS.Intrinsic("block.set")] public static bool SetBlock(string id, MCS.Position pos) => default;
            [MCS.Intrinsic("block.setobj")] public static bool SetBlockObject(BlockLib.Block block, MCS.Position pos) => default;
            [MCS.Intrinsic("block.fill")] public static bool FillBlock(string id, MCS.Position from, MCS.Position to) => default;
            [MCS.Intrinsic("block.fillobj")] public static bool FillBlockObject(BlockLib.Block block, MCS.Position from, MCS.Position to) => default;
            [MCS.Intrinsic("block.is")] public static bool IsBlock(string id, MCS.Position pos) => default;
            [MCS.Intrinsic("block.isobj")] public static bool IsBlockObject(BlockLib.Block block, MCS.Position pos) => default;

            [MCS.Intrinsic("setworldspawn")] public static void SetWorldSpawn(MCS.Position pos) { }
            [MCS.Intrinsic("reload")] public static void Reload() { }

            /// A raw execute condition, e.g. m.Check("block ~ ~ ~ minecraft:stone") → execute if block ...
            [MCS.Intrinsic("check")] public static bool Check(string condition) => default;
            /// Runs a command and returns its result value (execute store result). Interpolated values become macro arguments.
            [MCS.Intrinsic("result")] public static int Result(string command) => default;
            /// Runs a command and returns whether it succeeded.
            [MCS.Intrinsic("success")] public static bool Success(string command) => default;
            /// Random integer in [min, max] (inclusive).
            [MCS.Intrinsic("random")] public static int Random(int min, int max) => default;
            [MCS.Intrinsic("schedule")] public static void Schedule(System.Action function, int ticks) { }
            [MCS.Intrinsic("schedule.clear")] public static void ClearSchedule(System.Action function) { }
        }
        """;
}
